<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#dd0100; --blue:#225095; --yellow:#f9d01e;
    --black:#0a0a0a; --white:#f6f5f0; --grey:#d8d6d0;
    --line:14px;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{
    font-family:"Space Grotesk",Helvetica,Arial,sans-serif;
    background:var(--white); color:var(--black);
    line-height:1.55;
  }
  .wrap{max-width:1080px;margin:0 auto;padding:0 24px}

  /* ---- header ---- */
  header{border-bottom:var(--line) solid var(--black)}
  .masthead{display:flex;align-items:stretch;min-height:64px}
  .masthead .chip{width:64px}
  .masthead .chip.red{background:var(--red)}
  .masthead .chip.blue{background:var(--blue)}
  .masthead .chip.yellow{background:var(--yellow)}
  .masthead .title{flex:1;display:flex;align-items:center;padding:0 24px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:.85rem}

  /* ---- hero composition ---- */
  .hero{padding:56px 0}
  .hero-grid{display:grid;gap:0;border:var(--line) solid var(--black);background:var(--black);grid-template-columns:3fr 2fr;grid-template-rows:minmax(320px,52vh) 1fr 1fr;min-height:70vh}
  .cell{position:relative;padding:28px}
  .cell.red{grid-column:2;grid-row:1/3;background:var(--red)}
  .cell.top{grid-column:1;grid-row:1;background:var(--white);display:flex;flex-direction:column;justify-content:center}
  .cell.white{grid-column:1;grid-row:2;background:var(--white)}
  .cell.blue{grid-column:1;grid-row:3;background:var(--blue);color:var(--white)}
  .cell.yellow{grid-column:2;grid-row:3;background:var(--yellow)}
  .hero h1{font-size:clamp(1.9rem,4.5vw,3.4rem);line-height:1.05;font-weight:700;letter-spacing:-.01em}
  .hero .kicker{display:inline-block;border:3px solid var(--black);padding:6px 14px;font-size:.75rem;letter-spacing:.2em;text-transform:uppercase;margin-bottom:24px;align-self:flex-start}
  .hero p.lede{margin-top:20px;max-width:34ch;font-size:1.05rem}
  .meta{list-style:none;font-size:.85rem;letter-spacing:.06em}
  .meta li{padding:6px 0;border-bottom:2px solid rgba(0,0,0,.25)}
  .meta li:last-child{border-bottom:none}
  .meta strong{display:block;text-transform:uppercase;font-size:.7rem;letter-spacing:.2em;opacity:.75}
  .cell.yellow .meta li{border-bottom-color:rgba(0,0,0,.3)}

  /* ---- sections ---- */
  section{padding:72px 0}
  section + section{border-top:var(--line) solid var(--black)}
  .sec-label{display:inline-block;background:var(--black);color:var(--white);padding:6px 14px;font-size:.72rem;letter-spacing:.22em;text-transform:uppercase;margin-bottom:28px}
  h2{font-size:clamp(1.5rem,3vw,2.2rem);line-height:1.1;margin-bottom:20px;font-weight:700}
  .cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:var(--line)}
  .card{border:6px solid var(--black);padding:28px;background:var(--white)}
  .card.red{background:var(--red);color:#fff;border-color:var(--black)}
  .card h3{font-size:1rem;text-transform:uppercase;letter-spacing:.14em;margin-bottom:12px}
  .card p{font-size:.95rem}

  /* principles list */
  .principles{list-style:none;display:grid;gap:var(--line)}
  .principles li{border:6px solid var(--black);padding:20px 24px;display:flex;gap:18px;align-items:baseline}
  .principles .n{font-weight:700;font-size:1.4rem;min-width:2ch}
  .principles li:nth-child(1) .n{color:var(--red)}
  .principles li:nth-child(2) .n{color:var(--blue)}
  .principles li:nth-child(3) .n{color:#b99500}

  /* why it matters */
  .matters{background:var(--grey)}

  /* ---- footer / CTA ---- */
